 }
 ],
 "type": "input_source_if"
 }
 ],
 "from": {
 "key_code": "fn"
 },
 "parameters": {
 "basic.to_if_alone_timeout_milliseconds": 500,
 "basic.to_if_held_down_threshold_milliseconds": 100
 },
 "to": [
 {
 "key_code": "fn",
 "lazy": true
 }
 ],
 "to_if_alone": [
 {
 "select_input_source": {
 "input_source_id": "^com\\.apple\\.keylayout\\.Russian$"
 }
 }
 ],
 "to_if_held_down": [
 {
 "key_code": "fn"
 }
 ],
 "to_if_other_key_pressed": [
 {
 "other_keys": [
 {
 "any": "key_code"
 },
 {
 "any": "consumer_key_code"
 }
 ],
 "to": [
 {
 "key_code": "fn"
 }
 ]
 }
 ],
 "type": "basic"
 },
 {
 "conditions": [
 {
